<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { Activity, ArrowDownToLine, ArrowRight, ArrowUpFromLine, CalendarDays, Package, RefreshCw, TrendingDown, Warehouse } from '@lucide/vue'
import PageHeader from '../components/PageHeader.vue'
import FeedbackMessage from '../components/FeedbackMessage.vue'
import { allPages, queryString, request } from '../services/api'
import { useFeedback } from '../composables/useFeedback'
import type { ConsumptionReport, Department, Product } from '../types/api'

const { busy, error, setError } = useFeedback(); const products = ref<Product[]>([]); const departments = ref<Department[]>([]); const report = ref<ConsumptionReport | null>(null)
const today = new Date()
const formatLocalDate = (date: Date) => `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-${String(date.getDate()).padStart(2, '0')}`
const from = ref(formatLocalDate(new Date(today.getFullYear(), today.getMonth(), 1))); const to = ref(formatLocalDate(today))
const lowStock = computed(() => products.value.filter(product => product.current_stock <= product.minimum_stock).sort((first, second) => first.current_stock - second.current_stock))
const totalConsumed = computed(() => report.value?.departments.reduce((total, department) => total + department.consumed_quantity, 0) ?? 0)
const consumedItems = computed(() => report.value ? report.value.departments.flatMap(department => department.products.map(product => ({ ...product, department: department.name }))).sort((first, second) => second.consumed_quantity - first.consumed_quantity).slice(0, 6) : [])
async function load() {
  busy.value = true; error.value = ''
  try {
    const [loadedProducts, loadedDepartments, consumption] = await Promise.all([allPages<Product>('/products'), allPages<Department>('/departments'), request<{ data: ConsumptionReport }>(`/reports/consumption?${queryString({ from: from.value, to: to.value })}`)])
    products.value = loadedProducts; departments.value = loadedDepartments; report.value = consumption.data
  } catch (cause) { setError(cause) } finally { busy.value = false }
}
onMounted(load)
</script>

<template><div class="page-enter"><PageHeader eyebrow="PAINEL DE CONTROLE" title="Visão geral" description="Acompanhe seu estoque e as movimentações do período."><template #action><button class="button button-outline" :disabled="busy" @click="load"><RefreshCw :size="16" :class="{ spinning: busy }" /> Atualizar dados</button></template></PageHeader><FeedbackMessage :message="error" /><div class="filter-strip"><span class="filter-icon"><CalendarDays :size="16" /></span><span class="filter-label">Consumo entre</span><input v-model="from" class="date-input" type="date" :max="to" /><span class="filter-separator">e</span><input v-model="to" class="date-input" type="date" :min="from" /><button class="button button-dark button-small" :disabled="busy" @click="load">{{ busy ? 'Buscando…' : 'Aplicar período' }}</button><span v-if="report" class="period-note">{{ departments.length }} setores cadastrados</span></div>
  <section class="metric-grid"><article class="metric-card"><div class="metric-top"><span class="metric-icon icon-lilac"><Package :size="18" /></span><span class="metric-tag">CADASTRO</span></div><div class="metric-number">{{ busy ? '—' : products.length }}</div><div class="metric-caption">Produtos cadastrados</div><div class="metric-foot"><span class="metric-foot-dot dot-lilac"></span>Dados de todas as páginas</div></article><article class="metric-card"><div class="metric-top"><span class="metric-icon icon-orange"><TrendingDown :size="18" /></span><span class="metric-tag">ATENÇÃO</span></div><div class="metric-number">{{ busy ? '—' : lowStock.length }}<span class="metric-unit">{{ !busy && lowStock.length ? 'produtos' : '' }}</span></div><div class="metric-caption">Abaixo do estoque mínimo</div><div class="metric-foot" :class="lowStock.length ? 'status-warn' : ''"><span class="metric-foot-dot dot-orange"></span>{{ lowStock.length ? 'Requer acompanhamento' : 'Tudo dentro do mínimo' }}</div></article><article class="metric-card"><div class="metric-top"><span class="metric-icon icon-green"><ArrowDownToLine :size="18" /></span><span class="metric-tag">PERÍODO</span></div><div class="metric-number">{{ busy ? '—' : totalConsumed.toLocaleString('pt-BR') }}<span class="metric-unit">un.</span></div><div class="metric-caption">Consumo registrado</div><div class="metric-foot"><span class="metric-foot-dot dot-green"></span>{{ report ? `${from.slice(8, 10)}/${from.slice(5, 7)} — ${to.slice(8, 10)}/${to.slice(5, 7)}` : 'Aguardando dados' }}</div></article><article class="metric-card"><div class="metric-top"><span class="metric-icon icon-blue"><Warehouse :size="18" /></span><span class="metric-tag">SETORES</span></div><div class="metric-number">{{ busy ? '—' : departments.length }}</div><div class="metric-caption">Setores cadastrados</div><div class="metric-foot"><span class="metric-foot-dot dot-blue"></span>Consumo por setor no relatório</div></article></section>
  <div class="dashboard-grid"><section class="panel stock-panel"><div class="panel-heading"><div><div class="panel-title-line"><span class="panel-title-icon icon-orange"><TrendingDown :size="16" /></span><h2>Estoque abaixo do mínimo</h2></div><p>Produtos que precisam de reposição</p></div><RouterLink to="/products" class="text-link">Ver produtos <ArrowRight :size="14" /></RouterLink></div><div v-if="busy" class="loading-state"><span class="spinner"></span>Carregando dados da API…</div><div v-else-if="lowStock.length" class="table-wrap"><table class="data-table stock-table"><thead><tr><th>PRODUTO</th><th>SKU</th><th>DISPONÍVEL</th><th>MÍNIMO</th><th>STATUS</th></tr></thead><tbody><tr v-for="product in lowStock.slice(0, 6)" :key="product.id"><td><span class="table-product-icon"><Package :size="15" /></span><strong>{{ product.name }}</strong></td><td class="muted-cell">{{ product.sku }}</td><td><strong class="stock-number-low">{{ product.current_stock }} un.</strong></td><td class="muted-cell">{{ product.minimum_stock }} un.</td><td><span class="status-pill status-low">Abaixo do mínimo</span></td></tr></tbody></table></div><div v-else class="empty-state"><span class="empty-state-icon"><Package :size="22" /></span><strong>Nenhum alerta de estoque</strong><span>{{ products.length ? 'Todos os produtos estão dentro do nível mínimo.' : 'Cadastre seu primeiro produto para começar.' }}</span><RouterLink v-if="!products.length" class="button button-outline button-small" to="/products">Cadastrar produto</RouterLink></div><div v-if="lowStock.length > 6" class="panel-footer">Exibindo 6 de {{ lowStock.length }} produtos que precisam de atenção.</div></section>
  <section class="panel activity-panel"><div class="panel-heading"><div><div class="panel-title-line"><span class="panel-title-icon icon-green"><Activity :size="16" /></span><h2>Consumo por produto</h2></div><p>Saídas registradas no período selecionado</p></div><RouterLink to="/reports" class="icon-link" aria-label="Ver relatórios"><ArrowRight :size="17" /></RouterLink></div><div v-if="busy" class="loading-state"><span class="spinner"></span>Carregando consumo…</div><div v-else-if="consumedItems.length" class="consumption-list"><div v-for="(item, index) in consumedItems" :key="`${item.id}-${item.department}`" class="consumption-item"><span class="consumption-index">0{{ index + 1 }}</span><div class="consumption-info"><strong>{{ item.name }}</strong><span>{{ item.department }} · {{ item.sku }}</span><div class="consumption-progress"><span :style="{ width: `${Math.max(9, (item.consumed_quantity / Math.max(...consumedItems.map(entry => entry.consumed_quantity))) * 100)}%` }"></span></div></div><strong class="consumption-value">{{ item.consumed_quantity }} <small>un.</small></strong></div></div><div v-else class="empty-state empty-small"><span class="empty-state-icon"><ArrowUpFromLine :size="21" /></span><strong>Nenhuma saída neste período</strong><span>As movimentações OUT aparecerão aqui.</span></div><RouterLink to="/reports" class="activity-link">Ver relatório completo <ArrowRight :size="14" /></RouterLink></section></div>
  <section class="bottom-insight"><div class="insight-icon"><Warehouse :size="18" /></div><div><strong>Estoque gerido com clareza.</strong><span> Cadastre produtos, registre movimentações e acompanhe o consumo de cada setor em relatórios.</span></div><RouterLink to="/reports" class="insight-link">Explorar relatórios <ArrowRight :size="14" /></RouterLink></section></div></template>
